//! Frozen evaluation opening suite.
//!
//! Openings are deterministic legal prefixes generated by Recur64 from a
//! recorded seed. They are used **only** for evaluation (arena / raw-policy
//! matches), never for self-play generation, and are versioned.

use std::path::Path;

use serde::{Deserialize, Serialize};

use recur64_core::GameState;
use recur64_search::Rng;

/// A versioned opening suite.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OpeningSuite {
    pub version: u32,
    pub provenance: String,
    /// FEN of the position after the opening prefix.
    pub openings: Vec<String>,
}

impl OpeningSuite {
    pub fn load(path: &Path) -> anyhow::Result<Self> {
        Ok(toml::from_str(&std::fs::read_to_string(path)?)?)
    }

    pub fn save(&self, path: &Path) -> anyhow::Result<()> {
        std::fs::write(path, toml::to_string_pretty(self)?)?;
        Ok(())
    }

    pub fn len(&self) -> usize {
        self.openings.len()
    }

    pub fn is_empty(&self) -> bool {
        self.openings.is_empty()
    }
}

/// Generate `count` openings of `plies` random legal moves each.
pub fn generate_openings(count: usize, plies: usize, seed: u64) -> Vec<String> {
    let mut out = Vec::with_capacity(count);
    for i in 0..count {
        let mut rng = Rng::new(seed.wrapping_add(i as u64));
        let mut state = GameState::startpos();
        for _ in 0..plies {
            if state.is_terminal() {
                break;
            }
            let legal = state.legal_standard_moves();
            if legal.is_empty() {
                break;
            }
            let mv = legal[(rng.next_u64() as usize) % legal.len()];
            state.apply(mv).expect("generated opening move is legal");
        }
        out.push(state.to_fen());
    }
    out
}
